#include "domain.hpp"
#include <iostream>
#include <utility>
#include <sstream>
#include <stdexcept>
int main(){academy::Board b;academy::Normal normal;academy::Urgent urgent;int checks=0;
 auto check=[&](bool ok){if(ok)++checks;else std::cout<<"FAIL\n";};
 check(b.total(normal)==10);check(b.total(urgent)==20);
 b.replace({{2,3},{3,4}},false);check(b.total(normal)==7);check(b.total(urgent)==14);
 academy::Board copy=b;copy.replace({},false);check(copy.total(normal)==0);check(b.total(normal)==7);
 auto reject=[&](std::vector<academy::Task> v,bool fail){auto before=b.tasks();try{b.replace(std::move(v),fail);return false;}catch(const std::exception&){if(b.tasks().size()!=before.size())return false;for(std::size_t i=0;i<before.size();++i)if(b.tasks()[i].id!=before[i].id||b.tasks()[i].minutes!=before[i].minutes)return false;return true;}};
 check(reject({{2,1},{2,2}},false));check(reject({{0,1}},false));check(reject({{1,-1}},false));check(reject({{1,2}},true));
 check(academy::bounded(0,0,100)&&!academy::bounded(101,0,100));
 std::ostringstream out;academy::write_report(out,b,normal);check(out.str()=="tasks 2 score 7\n2 3\n3 4\n");
 std::cout<<"PASS "<<checks<<'\n';return checks==12?0:1;}

